  ]),
  allowPublicProjects: z.boolean(),
  requireTwoFactor: z.boolean(),
  digestHourUtc: z.number().int().min(0).max(23),
  enabledFlagOverrides: z.array(z.string()),
};

/** A complete settings block; the defaults only apply when creating an org. */
export const organizationSettingsSchema = z.object({
  defaultIssueStatus: settingFields.defaultIssueStatus.default("backlog"),
  allowPublicProjects: settingFields.allowPublicProjects.default(false),
  requireTwoFactor: settingFields.requireTwoFactor.default(false),
  digestHourUtc: settingFields.digestHourUtc.default(7),
  enabledFlagOverrides: settingFields.enabledFlagOverrides.default([]),
});

/**
 * A partial settings patch. Keys that are absent stay absent, so they are
 * left alone when merged over the stored settings. Do not build this from
 * `organizationSettingsSchema.partial()`: Zod keeps `.default()` under
 * `.partial()`, which would reset every key the caller did not send.
 */
export const organizationSettingsPatchSchema = z
  .object(settingFields)
  .partial();

